    static int max;
    public static void main (String[] args) throws java.lang.Exception
	{
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int k = fr.nextInt();
        int arr[] = new int[n];
        for(int i=0;i<n;i++){
            arr[i] = fr.nextInt();
        }
        int even = 0, odd = 0;
        ArrayList<Integer> al = new ArrayList<>();
        for(int i=0;i<n;i++){
            if(i!=0){
                if(even == odd){
                    al.add(Math.abs(arr[i]-arr[i-1]));
                }
            }
            if(arr[i]%2 == 0){
                even++;
            }
            else{
                odd++;
            }
